<div class="d-flex justify-content-between align-items-center mb-4"><h2>Products</h2><a href="<?= site_url('admin/products/add') ?>" class="btn btn-primary"><i class="fa-solid fa-plus"></i> Add Product</a></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0 admin-table"><thead><tr><th class="no-sort">Image</th><th>Name</th><th>Author</th><th>Category</th><th>Price</th><th>Qty</th><th class="no-sort">Flags</th><th class="no-sort">Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?php if(!empty($p->image)): ?><img class="thumb" src="<?= product_image_url($p->image) ?>"><?php endif; ?></td><td><?= html_escape($p->pr_name) ?></td><td><?= html_escape($p->pr_author_name) ?></td><td><?= html_escape($p->pr_cate) ?></td><td>₹<?= number_format((float)$p->pr_price,2) ?></td><td><?= html_escape($p->pr_qty) ?></td><td><?php if(!empty($p->is_bestseller)): ?><span class="badge bg-warning text-dark">Best Seller</span><?php endif; ?> <?php if(!empty($p->is_newarrival)): ?><span class="badge bg-info">New</span><?php endif; ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/products/edit/'.$p->id) ?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="<?= site_url('admin/products/delete/'.$p->id) ?>" onclick="return confirm('Delete this product?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></div>
